-- Base de conocimiento del agente Meta Ads (Sprint 1, doc 0007).
-- Reglas del Excel "Meta Ads Rules and Missing Information Summary" (60 reglas, todas "Opinión de experto", una sola guía de remarketing).
-- Son REFERENCIAS a contrastar con datos propios, nunca órdenes. La columna aplicabilidad es una clasificación hecha por Claude
-- el 2026-10-02 y debe revisarla el dueño. Los IDs se normalizan a 3 dígitos (R0010 -> R010); el original queda en codigo_origen.

create table if not exists public.agente_reglas_marketing (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  codigo text not null,
  codigo_origen text,
  capa text not null check (capa in ('meta_general','remarketing','performance','flujo')),
  categoria text,
  regla text not null,
  cuando_aplica text,
  accion text,
  metrica text,
  umbral text,
  ejemplo text,
  nivel_evidencia text,
  fuente text not null,
  plataforma text not null default 'meta' check (plataforma in ('meta','google','ambas')),
  aplicabilidad text not null check (aplicabilidad in ('aplica','parcial','requiere_web','fuera_de_alcance','sin_contenido')),
  motivo_aplicabilidad text,
  estado text not null default 'referencia' check (estado in ('referencia','confirmada_con_datos','contradicha_con_datos','descartada')),
  evidencia jsonb,
  creado_at timestamptz not null default now(),
  actualizado_at timestamptz not null default now(),
  unique (organization_id, codigo)
);

create table if not exists public.agente_negocio_hechos (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  categoria text not null check (categoria in ('servicio','precio','publico','geografia','proceso','pago','definicion')),
  clave text not null,
  valor text not null,
  vigente_desde date not null default current_date,
  vigente_hasta date,
  fuente text not null,
  unique (organization_id, clave, vigente_desde)
);

alter table public.agente_reglas_marketing enable row level security;
alter table public.agente_negocio_hechos enable row level security;
drop policy if exists panel_read on public.agente_reglas_marketing;
create policy panel_read on public.agente_reglas_marketing for select to authenticated
  using (organization_id = (select private.get_user_org_id()));
drop policy if exists panel_read on public.agente_negocio_hechos;
create policy panel_read on public.agente_negocio_hechos for select to authenticated
  using (organization_id = (select private.get_user_org_id()));
revoke all on public.agente_reglas_marketing, public.agente_negocio_hechos from anon;
revoke insert, update, delete on public.agente_reglas_marketing, public.agente_negocio_hechos from authenticated;
grant select on public.agente_reglas_marketing, public.agente_negocio_hechos to authenticated;
grant select, insert, update, delete on public.agente_reglas_marketing, public.agente_negocio_hechos to service_role;

insert into public.agente_reglas_marketing
  (organization_id, codigo, codigo_origen, capa, categoria, regla, cuando_aplica, accion, metrica, umbral, ejemplo, nivel_evidencia, fuente, plataforma, aplicabilidad, motivo_aplicabilidad)
select '00000000-0000-0000-0000-000000000001'::uuid, x.codigo, x.codigo_origen, x.capa, x.categoria, x.regla, x.cuando_aplica, x.accion, x.metrica, x.umbral, x.ejemplo,
       x.nivel_evidencia, x.fuente, x.plataforma, x.aplicabilidad, x.motivo
from jsonb_to_recordset($j$[{"codigo":"R001","codigo_origen":"R001","capa":"performance","categoria":"Estructura de campaña","regla":"Top of funnel campaigns should receive the largest portion of the total ad budget.","cuando_aplica":"When structuring a multi-stage paid media funnel.","accion":"Allocate 50-60% (or 40-50%) of the total budget to top-of-funnel campaigns targeting qualified cold audiences.","metrica":"ROAS, Traffic volume","umbral":"50-60% or 40-50%","ejemplo":"In a professional paid media funnel, Top of funnel (TOF) gets 50-60% of the budget on qualified cold audiences.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección El embudo de paid media profesional 1","plataforma":"meta","aplicabilidad":"parcial","motivo":"Reparto TOF/MOF/BOF pensado para tiendas con web; en clic-a-WhatsApp el MOF/BOF son segmentos de WhatsApp y con presupuesto pequeño no se fija un reparto sin datos propios."},{"codigo":"R002","codigo_origen":"R002","capa":"performance","categoria":"Estructura de campaña","regla":"Middle of funnel remarketing should receive a moderate portion of the budget.","cuando_aplica":"When structuring a paid media funnel for website traffic and interactions.","accion":"Allocate 25-30% of the total budget to middle-of-funnel remarketing.","metrica":"ROAS, Engagement","umbral":"25-30%","ejemplo":"Middle of funnel (MOF) receives 25-30% in remarketing of web traffic and interactions.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección El embudo de paid media profesional 1","plataforma":"meta","aplicabilidad":"parcial","motivo":"Idem R001: el remarketing de FLUJO es de WhatsApp/engagement, no de tráfico web."},{"codigo":"R003","codigo_origen":"R003","capa":"performance","categoria":"Estructura de campaña","regla":"Bottom of funnel critical remarketing should receive a dedicated budget portion.","cuando_aplica":"When targeting high-intent audiences like abandoned carts or checkouts.","accion":"Allocate 15-20% (or 20-25%) of the total budget to bottom-of-funnel remarketing.","metrica":"ROAS, Cost per conversion","umbral":"15-20% or 20-25%","ejemplo":"Bottom of funnel (BOF) receives 15-20% in critical remarketing (carts, initiated checkouts).","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección El embudo de paid media profesional 1","plataforma":"meta","aplicabilidad":"parcial","motivo":"Idem R001: no hay carritos ni checkout; el equivalente es \"recibió Pix y no pagó\"."},{"codigo":"R004","codigo_origen":"R004","capa":"meta_general","categoria":"Medición y atribución","regla":"Meta CAPI implementation prevents significant tracking data loss compared to using Pixel alone.","cuando_aplica":"When tracking conversions post-iOS 14.5+.","accion":"Implement Conversions API (CAPI) to send data directly from the server to Meta.","metrica":"Conversion volume, Data accuracy","umbral":"30-60%","ejemplo":"Without CAPI, you lose 30-60% of tracking data due to users blocking Pixel tracking on iOS 14.5+.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Fundamento 2: API de Conversiones (CAPI) de Meta 1","plataforma":"meta","aplicabilidad":"parcial","motivo":"El principio (no depender solo del Pixel) aplica; para WhatsApp la señal es la conversación. Verificar si se envían a Meta eventos de negocio (pago)."},{"codigo":"R005","codigo_origen":"R005","capa":"remarketing","categoria":"Segmentación/Audiencia","regla":"Targeting recent website visitors excluding spenders yields high performance.","cuando_aplica":"When setting up general website remarketing.","accion":"Target website visitors from the last 7 to 30 days while excluding buyers or leads.","metrica":"ROAS","umbral":"4-10x","ejemplo":"Website visitors last 7-30 days (excluding converters) expects a ROAS of 4-10x.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Audiencia 1: Visitantes web últimos 7-30 días 1","plataforma":"meta","aplicabilidad":"requiere_web","motivo":"Exige una web con Pixel; el flujo actual es clic a WhatsApp sin web confirmada."},{"codigo":"R006","codigo_origen":"R006","capa":"remarketing","categoria":"Segmentación/Audiencia","regla":"Cart abandoner remarketing is highly effective within a short timeframe.","cuando_aplica":"When re-engaging users who added items to a cart.","accion":"Target cart abandoners within a 3 to 7 day window (or 24 hours to 7 days).","metrica":"ROAS","umbral":"8-20x","ejemplo":"Abandoned carts (3-7 days) expected performance is ROAS 8-20x.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Audiencia 2: Carritos abandonados 1","plataforma":"meta","aplicabilidad":"fuera_de_alcance","motivo":"Carritos abandonados: FLUJO no tiene carrito."},{"codigo":"R007","codigo_origen":"R007","capa":"remarketing","categoria":"Segmentación/Audiencia","regla":"Checkout abandoner remarketing achieves extremely high ROAS within a narrow window.","cuando_aplica":"When re-engaging users who initiated checkout without completing.","accion":"Target users who initiated checkout within 1 to 3 days.","metrica":"ROAS","umbral":"10-30x","ejemplo":"Initiated checkout without completing (1-3 days) achieves ROAS 10-30x when well managed.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Audiencia 3: Iniciaron checkout sin completar 1","plataforma":"meta","aplicabilidad":"fuera_de_alcance","motivo":"Checkout abandonado: FLUJO no tiene checkout."},{"codigo":"R008","codigo_origen":"R008","capa":"remarketing","categoria":"Segmentación/Audiencia","regla":"Social media engagers can be remarketed to effectively over a 90-day window.","cuando_aplica":"When retargeting Instagram profile, post, or ad interacters.","accion":"Target Instagram interactions from the past 90 days.","metrica":"ROAS","umbral":"5-12x","ejemplo":"Interactions with Instagram over last 90 days yields ROAS 5-12x.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Audiencia 4: Interacciones con tu Instagram últimos 90 días 1","plataforma":"meta","aplicabilidad":"aplica","motivo":"Interacciones de Instagram/Facebook sí existen en Meta."},{"codigo":"R009","codigo_origen":"R009","capa":"remarketing","categoria":"Segmentación/Audiencia","regla":"High-duration video viewers represent a qualified remarketing audience that circumvents Pixel limitations.","cuando_aplica":"When creating remarketing audiences on Meta without relying on website tracking.","accion":"Target users who watched 75% or more of your videos.","metrica":"ROAS","umbral":"75%","ejemplo":"Watched 75%+ of videos audience achieves expected ROAS of 6-15x and does not depend on Pixel.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Audiencia 5: Vieron 75%+ de tus videos 1","plataforma":"meta","aplicabilidad":"aplica","motivo":"Espectadores de video son un público de Meta sin Pixel."},{"codigo":"R010","codigo_origen":"R0010","capa":"remarketing","categoria":"Segmentación/Audiencia","regla":"Uploaded customer email and phone lists must be periodically refreshed.","cuando_aplica":"When using CRM list uploads for custom audiences.","accion":"Upload updated customer lists every 30 to 60 days.","metrica":"ROAS, Audience match freshness","umbral":"30-60 days","ejemplo":"Upload updated list every 30-60 days to keep it fresh; expected ROAS is 10-25x for reactivations.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Audiencia 6: Lista de clientes existentes 1","plataforma":"meta","aplicabilidad":"parcial","motivo":"Aplica solo si se suben teléfonos como público; requiere decisión del dueño sobre datos personales."},{"codigo":"R011","codigo_origen":"R0011","capa":"remarketing","categoria":"Segmentación/Audiencia","regla":"High LTV seed lists generate the most effective lookalike audiences.","cuando_aplica":"When creating lookalike audiences to acquire users similar to top buyers.","accion":"Use a seed list consisting of top 20% highest LTV customers and set percentage size to 1-3%.","metrica":"ROAS","umbral":"1-3%","ejemplo":"Lookalike based on top 20% LTV customers at 1-3% size produces expected ROAS 3-7x.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Audiencia 7: Lookalike de tus mejores clientes 1","plataforma":"meta","aplicabilidad":"parcial","motivo":"Semilla de clientes pagados; hoy hay pocos pagos, puede no alcanzar el tamaño mínimo."},{"codigo":"R012","codigo_origen":"R0012","capa":"performance","categoria":"Estructura de campaña","regla":"Meta Ads ad set counts should be consolidated under modern delivery algorithms.","cuando_aplica":"When structuring Meta Ads remarketing campaigns in the Andromeda era.","accion":"Limit campaign structure to 2-3 ad sets maximum per campaign.","metrica":"Campaign performance, Algorithmic optimization","umbral":"2-3","ejemplo":"Before: 8-10 ad sets. Now: 2-3 ad sets maximum; Andromeda decides better who to show what.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Cómo hacer remarketing en Meta Ads en la era Andromeda 1","plataforma":"meta","aplicabilidad":"aplica","motivo":"Consolidar conjuntos aplica; con presupuesto pequeño evita fragmentar."},{"codigo":"R013","codigo_origen":"R0013","capa":"remarketing","categoria":"Segmentación/Audiencia","regla":"Remarketing audiences on Meta should not be constricted with additional interest targeting.","cuando_aplica":"When targeting custom remarketing audiences in Meta Ads.","accion":"Leave remarketing audiences broad without adding extra interest filters.","metrica":"ROAS, Cost per conversion","umbral":null,"ejemplo":"Leave the remarketing audience broad, without additional interests.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Cómo hacer remarketing en Meta Ads en la era Andromeda 1","plataforma":"meta","aplicabilidad":"aplica","motivo":"Aplica a cualquier público de remarketing de Meta."},{"codigo":"R014","codigo_origen":"R0014","capa":"remarketing","categoria":"Creativos (imagen/video)","regla":"Multiple distinct creative assets per ad set are required for effective algorithmic matching in Meta.","cuando_aplica":"When setting up creative assets within Meta Ads remarketing ad sets.","accion":"Provide 5 to 10 distinct ad creatives per audience or ad set.","metrica":"Ad relevance, ROAS","umbral":"5-10","ejemplo":"Include 5-10 different creatives per audience so Andromeda can match correctly.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Cómo hacer remarketing en Meta Ads en la era Andromeda 1","plataforma":"meta","aplicabilidad":"parcial","motivo":"Referencia; con presupuesto pequeño 5-10 creativos por conjunto puede diluir el gasto."},{"codigo":"R015","codigo_origen":"R0015","capa":"performance","categoria":"Presupuesto y puja","regla":"Web remarketing campaigns in Meta should be allocated about a third of total spend.","cuando_aplica":"When distributing budget across Meta remarketing campaigns.","accion":"Allocate 25-35% of total budget to Web Remarketing campaigns.","metrica":"Conversion rate, Cost per acquisition","umbral":"25-35%","ejemplo":"Campaña 1: Remarketing Web (Visitantes + Carritos) budget allocation is 25-35% of total.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección La estructura recomendada para remarketing en Meta 2026 1","plataforma":"meta","aplicabilidad":"requiere_web","motivo":"Reparto basado en remarketing web."},{"codigo":"R016","codigo_origen":"R0016","capa":"performance","categoria":"Presupuesto y puja","regla":"Engagement remarketing campaigns should receive a dedicated minor budget share.","cuando_aplica":"When allocating budget to social engagement remarketing.","accion":"Allocate 15-20% of total budget to Engagement Remarketing (IG + Videos).","metrica":"Cost per lead, Cost per purchase","umbral":"15-20%","ejemplo":"Campaña 2: Remarketing Engagement budget allocation is 15-20% of total.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección La estructura recomendada para remarketing en Meta 2026 1","plataforma":"meta","aplicabilidad":"parcial","motivo":"Aplica como remarketing de engagement; el porcentaje no está validado para FLUJO."},{"codigo":"R017","codigo_origen":"R0017","capa":"performance","categoria":"Presupuesto y puja","regla":"Critical cart abandonment campaigns require a focused budget share for dynamic ad delivery.","cuando_aplica":"When setting up optional dynamic product ads for recent abandoned carts.","accion":"Allocate 10-15% of total budget to cart abandonment remarketing.","metrica":"ROAS, Abandonment recovery rate","umbral":"10-15%","ejemplo":"Campaña 3: Carrito Abandonado Crítico budget allocation is 10-15% of total.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección La estructura recomendada para remarketing en Meta 2026 1","plataforma":"meta","aplicabilidad":"fuera_de_alcance","motivo":"Carritos: no aplica."},{"codigo":"R018","codigo_origen":"R0018","capa":"performance","categoria":"Optimización y escalado","regla":"Search Remarketing (RLSA) yields high ROAS by targeting former site visitors with explicit search intent.","cuando_aplica":"When bidding on Google Search keywords for previous visitors.","accion":"Increase bid amounts and show tailored messaging on Google Search for past site visitors.","metrica":"ROAS","umbral":"8-25x","ejemplo":"Search Remarketing (RLSA) expected performance is ROAS 8-25x.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Plataforma 1: Search Remarketing (RLSA) 1","plataforma":"google","aplicabilidad":"fuera_de_alcance","motivo":"RLSA es Google Search; el agente es solo de Meta."},{"codigo":"R019","codigo_origen":"R0019","capa":"performance","categoria":"Optimización y escalado","regla":"Display remarketing impression frequency should be capped to prevent ad fatigue.","cuando_aplica":"When running Google Display Remarketing banners.","accion":"Limit display remarketing frequency to 3-5 impressions per week per user.","metrica":"CTR, Click fraud rate, Brand sentiment","umbral":"3-5 impressions per week","ejemplo":"Frecuencia limitada (3-5 impresiones por semana) on Display Remarketing.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Plataforma 2: Display Remarketing 1","plataforma":"google","aplicabilidad":"fuera_de_alcance","motivo":"Display es Google; el agente es solo de Meta."},{"codigo":"R020","codigo_origen":"R0020","capa":"performance","categoria":"Presupuesto y puja","regla":"Google Ads remarketing spend should be heavily weighted towards high-intent search lists.","cuando_aplica":"When allocating budget across Google Ads remarketing channels.","accion":"Allocate 60% of budget to Search RLSA, 20% to Display, 15% to Discovery, and 5% to YouTube.","metrica":"ROAS","umbral":"60% Search, 20% Display, 15% Discovery, 5% YouTube","ejemplo":"Distribution for Google Ads: 60% Search RLSA, 20% Display, 15% Discovery, 5% YouTube.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección El sistema integrado profesional para Google Ads 1","plataforma":"google","aplicabilidad":"fuera_de_alcance","motivo":"Reparto de Google Ads."},{"codigo":"R021","codigo_origen":"R0021","capa":"performance","categoria":"Optimización y escalado","regla":"Ad impression frequency must be controlled according to audience funnel warmth.","cuando_aplica":"When setting frequency caps across different stages of remarketing.","accion":"Cap cold audiences at 2-4 impressions/week, TOF at 3-6, MOF at 5-8, and BOF cart audiences at 8-15/week.","metrica":"Ad frequency, CTR, Cost per acquisition","umbral":"2-4 (Cold), 3-6 (TOF), 5-8 (MOF), 8-15 (BOF)","ejemplo":"Remarketing bottom of funnel (carrito): 8-15 impresiones por semana.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Frecuencia óptima 1","plataforma":"meta","aplicabilidad":"aplica","motivo":"Control de frecuencia por temperatura de audiencia; Meta reporta frecuencia."},{"codigo":"R022","codigo_origen":"R0022","capa":"remarketing","categoria":"Segmentación/Audiencia","regla":"Audience conversion rate decays significantly as time elapsed since last website interaction increases.","cuando_aplica":"When segmenting remarketing lists by time recency.","accion":"Categorize lists into 0-7 days (hot), 7-30 days (warm), 30-90 days (cold reactivable), and exclude/limit 90+ days.","metrica":"Conversion rate, ROAS","umbral":"0-7 days, 7-30 days, 30-90 days, 90+ days","ejemplo":"90+ days: very low conversion; generally not worth the investment.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Tiempo en lista de remarketing 1","plataforma":"meta","aplicabilidad":"parcial","motivo":"La caída por antigüedad se mide con interacción web; el análogo en WhatsApp son días desde la última conversación (dato propio a medir)."},{"codigo":"R023","codigo_origen":"R0023","capa":"remarketing","categoria":"Segmentación/Audiencia","regla":"Excluding recent converters is required to prevent wasted ad spend on existing buyers.","cuando_aplica":"When configuring audience targeting for acquisition or remarketing campaigns.","accion":"Always exclude users who purchased or converted in the last 7 to 30 days.","metrica":"Cost per acquisition, Wasted spend","umbral":"7-30 days","ejemplo":"Exclude recent converters: people who already bought in the last 7-30 days.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Exclusiones inteligentes 1","plataforma":"meta","aplicabilidad":"aplica","motivo":"Excluir clientes que ya pagaron es el caso más seguro y de mayor valor."},{"codigo":"R024","codigo_origen":"R0024","capa":"performance","categoria":"Cuándo pausar o cortar","regla":"Custom audiences smaller than a threshold size cannot be properly optimized by ad platform algorithms.","cuando_aplica":"When creating custom remarketing audience pools.","accion":"Do not run dedicated remarketing campaigns on audiences with fewer than 1,000 people.","metrica":"Algorithmic optimization, CPM","umbral":"1,000 people","ejemplo":"Audiencias demasiado pequeñas: Con menos de 1.000 personas, optimización imposible.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Errores típicos que hacen perder dinero en remarketing 1","plataforma":"meta","aplicabilidad":"aplica","motivo":"Tamaño mínimo de público aplica a cualquier público personalizado."},{"codigo":"R025","codigo_origen":"R0025","capa":"meta_general","categoria":"Medición y atribución","regla":"Platform-reported ROAS can reflect self-attribution rather than true incremental revenue.","cuando_aplica":"When evaluating ad campaign profitability solely from ad manager dashboards.","accion":"Validate platform metrics using pause tests, geo-split tests, post-purchase surveys, or external analytics every 3 months.","metrica":"Real Incremental ROAS, CAC","umbral":"Every 3 months","ejemplo":"Pause remarketing for 2 weeks to see if sales drop proportionally, evaluating true incrementality.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Cómo medir ROAS real de remarketing 1","plataforma":"meta","aplicabilidad":"aplica","motivo":"Ya es la premisa del sistema: contrastar lo que Meta reporta con pagos reales de Kommo/Supabase."},{"codigo":"R026","codigo_origen":"R0026","capa":"performance","categoria":"Fase de aprendizaje","regla":"Remarketing campaigns scale stably because audience pools naturally refresh from cold traffic inputs.","cuando_aplica":"When scaling budgets on warm vs cold campaigns.","accion":"Maintain a continuous flow of top-of-funnel cold traffic to refresh remarketing lists continuously.","metrica":"ROAS stability, CPA","umbral":null,"ejemplo":"Remarketing scales more stably because the audience is organically renewed with new traffic.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Razón 5: Permite escalar sin destruir rendimiento 1","plataforma":"meta","aplicabilidad":"parcial","motivo":"Depende de que haya tráfico frío constante; no verificado en FLUJO."},{"codigo":"R027","codigo_origen":"R0027","capa":"performance","categoria":"Presupuesto y puja","regla":"Remarketing produces lower CPC compared to cold audience targeting.","cuando_aplica":"When comparing click costs between cold and warm traffic.","accion":"Reinvest savings from cheaper warm traffic clicks into creative production for retargeting.","metrica":"CPC","umbral":"30-60% cheaper","ejemplo":"Compared to cold audiences, remarketing typically has 30-60% cheaper CPC.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Razón 2: CPC más bajos 1","plataforma":"meta","aplicabilidad":"parcial","motivo":"Referencia; contrastar con CPC propio."},{"codigo":"R028","codigo_origen":"R0028","capa":"performance","categoria":"Optimización y escalado","regla":"Remarketing campaigns generate high revenue efficiency relative to their small budget share.","cuando_aplica":"When planning overall ad account budget distribution.","accion":"Allocate 10-20% of total ad budget to remarketing to drive 30-50% of total revenue.","metrica":"Total Revenue, Overall ROAS","umbral":"10-20% budget / 30-50% revenue","ejemplo":"Remarketing can generate 30-50% of total sales with only 10-20% of your budget.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Los números que importan 1","plataforma":"meta","aplicabilidad":"parcial","motivo":"Referencia de e-commerce; contrastar con datos propios."},{"codigo":"R029","codigo_origen":"R0029","capa":"meta_general","categoria":"Medición y atribución","regla":"The vast majority of website visitors do not convert during their first visit.","cuando_aplica":"When measuring initial touchpoint conversion rates.","accion":"Implement remarketing to capture non-converting first-time visitors.","metrica":"Conversion rate","umbral":"96-98%","ejemplo":"96-98% of visitors do NOT buy on their first visit.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Tenés tráfico llegando a tu sitio o redes 1","plataforma":"meta","aplicabilidad":"requiere_web","motivo":"Habla de visitas web; el equivalente en FLUJO son conversaciones, a medir con datos propios."},{"codigo":"R030","codigo_origen":"R0030","capa":"performance","categoria":"Optimización y escalado","regla":"A minimum number of touchpoints is required prior to consumer purchase decisions.","cuando_aplica":"When designing multi-touch marketing funnels.","accion":"Sequentially retarget prospects to deliver 6 to 8 brand interactions.","metrica":"Conversion rate, Customer acquisition cost","umbral":"6-8 touchpoints","ejemplo":"A person needs 6-8 touchpoints before buying.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Los números que importan 1","plataforma":"meta","aplicabilidad":"parcial","motivo":"Referencia; la cantidad de contactos hasta el pago en FLUJO debe medirse."},{"codigo":"R031","codigo_origen":"R0031","capa":"performance","categoria":"Optimización y escalado","regla":"Absence of a remarketing strategy increases overall cost per customer.","cuando_aplica":"When running paid ad accounts without retargeting funnels.","accion":"Implement remarketing campaigns to prevent elevated customer acquisition costs.","metrica":"Cost per customer (CAC)","umbral":"60-80% higher","ejemplo":"Businesses without remarketing pay 60-80% more for each new customer.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Los números que importan 1","plataforma":"meta","aplicabilidad":"parcial","motivo":"Cifra de una guía comercial sobre remarketing; no tratar como dato propio."},{"codigo":"R032","codigo_origen":"R0032","capa":"remarketing","categoria":"Copy y titulares","regla":"Ad copy must match the prospective buyer's specific stage in the decision funnel.","cuando_aplica":"When writing ad copy for cold vs retargeted audiences.","accion":"Use educational copy for cold traffic, social proof for profile/video engagers, discount/benefits for web visitors, and urgency for cart abandoners.","metrica":"CTR, Conversion rate","umbral":null,"ejemplo":"Audiencia que agregó al carrito: mensaje de urgencia + facilidad.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección El sistema con remarketing inteligente 1","plataforma":"meta","aplicabilidad":"aplica","motivo":"Ajustar el mensaje a la etapa aplica a creativos de FLUJO."},{"codigo":"R033","codigo_origen":"R0033","capa":"remarketing","categoria":"Creativos (imagen/video)","regla":"Remarketing creatives must explicitly acknowledge prior brand familiarity.","cuando_aplica":"When selecting creative formats for retargeting campaigns.","accion":"Deploy customer testimonials, competitor comparisons, specific case studies, guarantees, and visual FAQs rather than cold ads.","metrica":"Conversion rate, ROAS","umbral":null,"ejemplo":"Use customer testimonials, competitor comparisons, and specific success cases for retargeting.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Tipos de creatividades efectivas 1","plataforma":"meta","aplicabilidad":"aplica","motivo":"Aplica a remarketing de FLUJO."},{"codigo":"R034","codigo_origen":"R0034","capa":"meta_general","categoria":"Medición y atribución","regla":"Meta Pixel base code installation must be placed across all site header sections.","cuando_aplica":"When manually setting up Meta Pixel on a website.","accion":"Insert base pixel code between  and  tags across all web pages.","metrica":"Tracking coverage, Event firing accuracy","umbral":null,"ejemplo":"Instalar código base en todas las páginas (entre  y ).","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Cómo instalarlo profesionalmente 1","plataforma":"meta","aplicabilidad":"requiere_web","motivo":"Exige instalar Pixel en una web."},{"codigo":"R035","codigo_origen":"R0035","capa":"meta_general","categoria":"Medición y atribución","regla":"Meta Pixel installation requires validation via helper tools prior to campaign launch.","cuando_aplica":"When verifying pixel implementation.","accion":"Use the Meta Pixel Helper Chrome extension to verify correct tag firing.","metrica":"Data accuracy","umbral":null,"ejemplo":"Verificar instalación con Meta Pixel Helper (extensión Chrome).","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Cómo instalarlo profesionalmente 1","plataforma":"meta","aplicabilidad":"requiere_web","motivo":"Exige Pixel instalado."},{"codigo":"R036","codigo_origen":"R0036","capa":"meta_general","categoria":"Medición y atribución","regla":"Advanced Matching activation improves Meta data matching efficiency.","cuando_aplica":"When setting up Meta Pixel parameters.","accion":"Enable Automatic Advanced Matching in Meta Pixel settings.","metrica":"Match rate, Attribution accuracy","umbral":null,"ejemplo":"Activar coincidencia avanzada para mejor matching.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Cómo instalarlo profesionalmente 1","plataforma":"meta","aplicabilidad":"requiere_web","motivo":"Exige Pixel instalado."},{"codigo":"R037","codigo_origen":"R0037","capa":"performance","categoria":"Presupuesto y puja","regla":"Post-purchase loyalty campaigns should receive a minimal budget fraction to drive cross-sells and up-sells.","cuando_aplica":"When setting up retention remarketing targeting previous buyers.","accion":"Allocate 5-10% of total budget to existing customer lists via Meta Customer Lists and Google Customer Match.","metrica":"LTV, Repeat Purchase Rate","umbral":"5-10%","ejemplo":"Etapa 4 – Post-compra (Loyalty): Presupuesto 5-10% del total.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Etapa 4 – Post-compra (Loyalty) 1","plataforma":"meta","aplicabilidad":"parcial","motivo":"Aplica si hay clientes recurrentes entre trámites; evaluar."},{"codigo":"R038","codigo_origen":"R0038","capa":"performance","categoria":"Cuándo pausar o cortar","regla":"Over-saturating remarketing audiences beyond target frequencies causes ad fatigue and performance penalties.","cuando_aplica":"When frequency metrics exceed standard thresholds in remarketing ad sets.","accion":"Rotate creative assets immediately when frequency limits are exceeded.","metrica":"CTR, CPM, Frequency","umbral":null,"ejemplo":"Si la frecuencia se dispara más allá de eso, rotás creatividades urgente.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Frecuencia, tiempo en lista y exclusiones inteligentes 1","plataforma":"meta","aplicabilidad":"aplica","motivo":"Saturación y fatiga aplican a cualquier remarketing."},{"codigo":"R039","codigo_origen":"R0039","capa":"performance","categoria":"Cuándo pausar o cortar","regla":"Pausing remarketing campaigns due to low reported platform ROAS harms cold campaign performance.","cuando_aplica":"When evaluating whether to turn off retargeting campaigns.","accion":"Do not pause remarketing campaigns purely on isolated low ROAS numbers without checking holistic funnel impact.","metrica":"Overall ROAS, Funnel conversion rate","umbral":null,"ejemplo":"Pausar campañas de remarketing por 'ROAS bajo': Sin remarketing, las frías rinden peor también.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Errores típicos que hacen perder dinero en remarketing 1","plataforma":"meta","aplicabilidad":"aplica","motivo":"Aplica: no pausar remarketing solo por el ROAS que reporta la plataforma."},{"codigo":"R040","codigo_origen":"R0040","capa":"remarketing","categoria":"Segmentación/Audiencia","regla":"Using home page URL visitors as a remarketing audience lowers intent relevance.","cuando_aplica":"When selecting web page URLs to define custom audience criteria.","accion":"Target specific landing page or product page URLs instead of general homepage URLs.","metrica":"Conversion rate, CPA","umbral":null,"ejemplo":"Usar la home como URL de remarketing: Cualquiera entra a la home. No discrimina intención.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Errores típicos que hacen perder dinero en remarketing 1","plataforma":"meta","aplicabilidad":"requiere_web","motivo":"Exige web."},{"codigo":"R041","codigo_origen":"R0041","capa":"remarketing","categoria":"Segmentación/Audiencia","regla":"Retargeting audience list durations extending to 180 days cause budget waste.","cuando_aplica":"When defining the lookback window for custom web audiences.","accion":"Restrict lookback windows to under 90 days for active conversion campaigns.","metrica":"ROAS, Conversion rate","umbral":"180 days","ejemplo":"Tiempos de lista demasiado largos: 180 días suele ser desperdicio.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Errores típicos que hacen perder dinero en remarketing 1","plataforma":"meta","aplicabilidad":"aplica","motivo":"Duración excesiva de públicos aplica a listas y engagement."},{"codigo":"R042","codigo_origen":"R0042","capa":"remarketing","categoria":"Segmentación/Audiencia","regla":"Tailored messaging by recency tiers improves conversion efficiency compared to uniform messaging.","cuando_aplica":"When creating ads for recency-segmented audiences.","accion":"Serve urgency offers to 1-7 day visitors, social proof to 8-30 day visitors, and educational content to 31-90 day visitors.","metrica":"Conversion rate, CTR","umbral":"1-7 days, 8-30 days, 31-90 days","ejemplo":"Visitantes 1-7 días: oferta + urgencia; Visitantes 8-30 días: prueba social + casos.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Frecuencia, tiempo en lista y exclusiones inteligentes 1","plataforma":"meta","aplicabilidad":"aplica","motivo":"Mensajes por antigüedad aplican a segmentos de WhatsApp."},{"codigo":"R043","codigo_origen":"R0043","capa":"performance","categoria":"Optimización y escalado","regla":"A multi-month implementation schedule provides structured execution for full cross-platform remarketing.","cuando_aplica":"When rolling out a new remarketing strategy from scratch.","accion":"Perform technical audits in week 1, audience creation in weeks 2-3, creative production in month 1, Meta launch in months 1-2, Google launch in month 2, and incrementality testing in months 4-6.","metrica":"Account ROAS, Implementation efficiency","umbral":"6 months","ejemplo":"Mes 4-6: Medición real de incrementalidad. Tests de pausa. Geo split tests.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Tu plan de remarketing profesional esta semana 1","plataforma":"ambas","aplicabilidad":"fuera_de_alcance","motivo":"Es un cronograma de implementación de la guía, no una regla de campaña."},{"codigo":"R044","codigo_origen":"R0044","capa":"remarketing","categoria":"Segmentación/Audiencia","regla":"Internal company traffic pollutes custom retargeting data if not explicitly excluded.","cuando_aplica":"When configuring global negative filters for website remarketing.","accion":"Exclude employee and supplier email addresses and IP visits from audience builds.","metrica":"Data purity, Wasted spend","umbral":null,"ejemplo":"Empleados/proveedores propios: sus emails en lista negativa.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Exclusiones inteligentes 1","plataforma":"meta","aplicabilidad":"parcial","motivo":"Aplica como excluir teléfonos del equipo y leads de prueba del análisis."},{"codigo":"R045","codigo_origen":"R0045","capa":"remarketing","categoria":"Segmentación/Audiencia","regla":"Geographic locations outside delivery capability must be excluded from retargeting.","cuando_aplica":"When configuring campaign location parameters.","accion":"Exclude regions or countries where product/service delivery is unavailable.","metrica":"Wasted spend, Conversion rate","umbral":null,"ejemplo":"Geografía irrelevante: lugares donde no entregás.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Exclusiones inteligentes 1","plataforma":"meta","aplicabilidad":"aplica","motivo":"FLUJO solo atiende en Brasil; excluir otras ubicaciones."},{"codigo":"R046","codigo_origen":"R0046","capa":"remarketing","categoria":"Segmentación/Audiencia","regla":"B2B remarketing campaigns should exclude non-buyer demographic interests.","cuando_aplica":"When running business-to-business retargeting.","accion":"Exclude student or non-decision-maker interests from B2B retargeting campaigns.","metrica":"CPA, Lead quality","umbral":null,"ejemplo":"Si vendés a empresas: excluir intereses de 'estudiantes universitarios'.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Exclusiones según contexto 1","plataforma":"meta","aplicabilidad":"fuera_de_alcance","motivo":"B2B: no es el caso."},{"codigo":"R047","codigo_origen":"R0047","capa":"remarketing","categoria":"Segmentación/Audiencia","regla":"Premium product retargeting should exclude bargain-seeking audiences.","cuando_aplica":"When advertising high-end or luxury products.","accion":"Exclude cheap deal and discount interest segments from premium retargeting campaigns.","metrica":"ROAS, Lead quality","umbral":null,"ejemplo":"Si productos premium: excluir audiencias de 'ofertas baratas'.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Exclusiones según contexto 1","plataforma":"meta","aplicabilidad":"fuera_de_alcance","motivo":"Producto premium: no es el caso."},{"codigo":"R048","codigo_origen":"R0048","capa":"meta_general","categoria":"Medición y atribución","regla":"Google Analytics 4 provides a third-party source of truth to cross-verify ad network performance.","cuando_aplica":"When setting up analytics for cross-channel tracking.","accion":"Link GA4 with Google Ads and use it to detect discrepancies against Meta and Google reported conversions.","metrica":"Attribution accuracy","umbral":null,"ejemplo":"GA4 Detecta discrepancias entre lo que dice Meta/Google vs realidad.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Fundamento 4: Google Analytics 4 (GA4) integrado 1","plataforma":"google","aplicabilidad":"fuera_de_alcance","motivo":"GA4 es Google y requiere web."},{"codigo":"R049","codigo_origen":"R0049","capa":"meta_general","categoria":"Medición y atribución","regla":"Google Tag Assistant enables verification of correct Google tag installation.","cuando_aplica":"When auditing Google tag deployment.","accion":"Verify tag firing across all pages using Google Tag Assistant.","metrica":"Data accuracy","umbral":null,"ejemplo":"Verificar con Google Tag Assistant.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Cómo configurarlo 1","plataforma":"google","aplicabilidad":"fuera_de_alcance","motivo":"Google Tag Assistant."},{"codigo":"R050","codigo_origen":"R0050","capa":"performance","categoria":"Optimización y escalado","regla":"Combining Meta Ads and Google Ads into an integrated system delivers superior returns compared to operating them independently.","cuando_aplica":"When managing multi-platform paid media accounts.","accion":"Feed Meta top-of-funnel traffic into Google Search RLSA and Display remarketing funnels.","metrica":"Account ROAS","umbral":null,"ejemplo":"Tráfico nuevo de Meta alimenta remarketing en Google y viceversa.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Por qué este sistema rinde tanto mejor 1","plataforma":"ambas","aplicabilidad":"fuera_de_alcance","motivo":"Integración Meta+Google; el agente es solo de Meta."},{"codigo":"R051","codigo_origen":"R0051","capa":"remarketing","categoria":"Creativos (imagen/video)","regla":"Dynamic Product Ads (DPA) drive high conversion rates for e-commerce abandoned cart remarketing.","cuando_aplica":"When retargeting e-commerce cart abandoners.","accion":"Utilize catalog dynamic product ads showing the exact product viewed.","metrica":"ROAS, Conversion rate","umbral":null,"ejemplo":"Anuncios dinámicos del catálogo (DPA) con mensaje específico: producto + incentivo.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Campaña 3 (opcional): Carrito Abandonado Crítico 1","plataforma":"meta","aplicabilidad":"fuera_de_alcance","motivo":"Dynamic Product Ads de e-commerce."},{"codigo":"R052","codigo_origen":"R0052","capa":"performance","categoria":"Pruebas A/B","regla":"Geographic split tests validate true incrementality of retargeting efforts.","cuando_aplica":"When assessing whether remarketing drives net new sales across regions.","accion":"Activate remarketing in one target city while keeping it paused in a comparable control city.","metrica":"Incremental Sales, Incremental ROAS","umbral":null,"ejemplo":"Geo split tests: activás remarketing en una ciudad, no en otra. Comparás ventas.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Métricas externas críticas 1","plataforma":"meta","aplicabilidad":"parcial","motivo":"Pruebas geográficas de incrementalidad: muestra probablemente insuficiente."},{"codigo":"R053","codigo_origen":"R0053","capa":"meta_general","categoria":"Medición y atribución","regla":"Post-purchase surveys help identify original discovery channels masked by retargeting attribution.","cuando_aplica":"When surveying newly converted customers at checkout.","accion":"Add a 'How did you hear about us?' survey to the post-purchase checkout screen.","metrica":"Attribution clarity","umbral":null,"ejemplo":"Post-purchase surveys: '¿cómo nos conociste?' en checkout.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Métricas externas críticas 1","plataforma":"meta","aplicabilidad":"aplica","motivo":"Nora puede preguntar cómo conoció a FLUJO; valida la atribución."},{"codigo":"R054","codigo_origen":"R0054","capa":"performance","categoria":"Pruebas A/B","regla":"A temporary pause test measures the exact sales lift provided by retargeting.","cuando_aplica":"When determining if remarketing converts users who would have purchased organically.","accion":"Pause remarketing campaigns for 2 weeks and compare total sales decline against baseline.","metrica":"Incremental Revenue","umbral":"2 weeks","ejemplo":"Test de pausado: pausá remarketing 2 semanas, mirá si las ventas caen proporcionalmente.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Métricas externas críticas 1","plataforma":"meta","aplicabilidad":"parcial","motivo":"Prueba de pausa de 2 semanas: costosa con volumen bajo; solo con datos suficientes."},{"codigo":"R055","codigo_origen":"R0055","capa":"meta_general","categoria":"Políticas y rechazos","regla":"Third-party display placements require regular placement auditing to clean up fraudulent clicks.","cuando_aplica":"When running Google Display Remarketing campaigns.","accion":"Audit placement reports regularly and exclude low-quality or fraudulent site domains.","metrica":"CTR, Fraudulent Click Rate, CPA","umbral":null,"ejemplo":"Auditá lugares de impresión periódicamente debido a tasas de fraude por click más altas en Display.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Plataforma 2: Display Remarketing 1","plataforma":"google","aplicabilidad":"fuera_de_alcance","motivo":"Placements de display de terceros."},{"codigo":"R056","codigo_origen":"R0056","capa":"remarketing","categoria":"Llamada a la acción","regla":"Re-engagement search copy should feature direct incentives to encourage returning visits.","cuando_aplica":"When drafting copy for Search Remarketing (RLSA) ads.","accion":"Include returning-visitor calls to action such as exclusive bonus offers.","metrica":"CTR, Conversion rate","umbral":null,"ejemplo":"Tu anuncio aparece arriba con mensaje 'Volvé a vernos: bonus exclusivo si te inscribís hoy'.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Plataforma 1: Search Remarketing (RLSA) 1","plataforma":"google","aplicabilidad":"fuera_de_alcance","motivo":"Search de Google."},{"codigo":"R057","codigo_origen":"R0057","capa":"flujo","categoria":"Clic-a-WhatsApp/mensajes","regla":"Direct messaging or click-to-WhatsApp ad rules specifically tailored for immigration procedures in Brazil for Spanish speakers are omitted.","cuando_aplica":"When searching for specific WhatsApp ad metrics for legal/immigration services in Brazil.","accion":"Apply general service remarketing and conversion tracking principles.","metrica":"NO ESPECIFICADO EN FUENTES","umbral":null,"ejemplo":"NO ESPECIFICADO EN FUENTES","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital 1","plataforma":"meta","aplicabilidad":"sin_contenido","motivo":"La fuente no trae contenido: es la brecha de conocimiento sobre clic-a-WhatsApp e inmigración en Brasil. No usar como regla."},{"codigo":"R058","codigo_origen":"R0058","capa":"performance","categoria":"Estructura de campaña","regla":"Consolidated remarketing structures allow automated ad delivery systems to optimize placement matching.","cuando_aplica":"When building Meta Ads account architecture.","accion":"Combine web visitors and cart abandoners into a single consolidated web remarketing ad set.","metrica":"Algorithmic Efficiency, CPM","umbral":null,"ejemplo":"Campaña 1: Remarketing Web con 1 conjunto de anuncios combinando visitantes y carritos.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección La estructura recomendada para remarketing en Meta 2026 1","plataforma":"meta","aplicabilidad":"aplica","motivo":"Estructuras consolidadas aplican."},{"codigo":"R059","codigo_origen":"R0059","capa":"performance","categoria":"Estructura de campaña","regla":"Combining video viewers and profile engagers into one ad set optimizes engagement remarketing performance.","cuando_aplica":"When retargeting social platform engagement.","accion":"Combine 90-day Instagram engagers and 75% video viewers into a single ad set.","metrica":"Cost per Lead, Cost per Purchase","umbral":"90 days / 75% view","ejemplo":"Audiencia combinada: interacciones IG 90 días + viewers 75% videos en 1 conjunto.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Campaña 2: Remarketing Engagement 1","plataforma":"meta","aplicabilidad":"aplica","motivo":"Aplica a audiencias de engagement."},{"codigo":"R060","codigo_origen":"R0060","capa":"meta_general","categoria":"Medición y atribución","regla":"Auditing technical setup prior to campaign optimization prevents wasted management effort on bad data.","cuando_aplica":"When troubleshooting poor account performance.","accion":"Perform a comprehensive technical audit of tracking tags before altering campaign optimizations.","metrica":"Data accuracy, Campaign ROAS","umbral":null,"ejemplo":"Auditar fundamentos técnicos primero ahorra meses de optimización ineficaz.","nivel_evidencia":"Opinión de experto","fuente":"Luzzi Digital, sección Una verdad importante 1","plataforma":"meta","aplicabilidad":"aplica","motivo":"Auditar la configuración técnica antes de optimizar aplica."}]$j$::jsonb) as x(codigo text, codigo_origen text, capa text, categoria text, regla text, cuando_aplica text, accion text, metrica text, umbral text, ejemplo text, nivel_evidencia text, fuente text, plataforma text, aplicabilidad text, motivo text)
on conflict (organization_id, codigo) do nothing;

-- Embudo real tal como lo definió el dueño (2026-10-02). Las definiciones de "calificado", "propuesta" y "Pix" por etapa
-- quedan PENDIENTES: no se inventan, las fija el dueño.
insert into public.agente_negocio_hechos (organization_id, categoria, clave, valor, fuente)
values ('00000000-0000-0000-0000-000000000001', 'proceso', 'embudo.etapas',
  'impresión > clic > conversación > Nora > lead > calificado > propuesta > Pix > pago > trámite > cliente > facturación',
  'dueño, 2026-10-02')
on conflict (organization_id, clave, vigente_desde) do nothing;

-- Precios vigentes: el agente los lee de la tabla comercial (no se copian, para que nunca queden desactualizados).
create or replace view public.agente_precios_vigentes with (security_invoker = true) as
select tramite_enum_id, tramite_nombre, precio, en_lista, orden, updated_at
from public.comercial_audios_pitch;
grant select on public.agente_precios_vigentes to authenticated;
